'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/switch/md-gb-switch.js';
import {SwitchElement} from '@material/web/labs/gb/components/switch/switch-element.js';

/**
 * A Material Design component. Wraps <md-gb-switch>.
 * Docs: https://material-web.dev/3.0/components/switch/
 */
export const MdSwitch = createComponent({
  react: React,
  tagName: 'md-gb-switch',
  elementClass: SwitchElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdSwitchProps = React.ComponentProps<typeof MdSwitch>;
